            );
          }

          return null;
        })
        .filter(Boolean); // 过滤掉任何无法识别的标签所产生的 null
    },
    get children() {
      // children 和 childNodes 在这个模拟中行为一致
      return this.childNodes;
    },
    appendChild(element) {
      this.innerHTML = (this.innerHTML ?? "") + element.outerHTML;
    },
    querySelectorAll(selector) {
      // 简化实现，假设总是查询 'p'
      if (selector.toLowerCase() === "p") {
